<?php
$approved=$invoice['status']==='approved';$status=['draft'=>'مسودة','approved'=>'معتمد','cancelled'=>'ملغي'][$invoice['status']]??$invoice['status'];$vendor=$approved?$invoice['vendor_code_snapshot'].' - '.$invoice['vendor_name_snapshot']:$invoice['current_vendor_code'].' - '.$invoice['current_vendor_name'];$project=$approved?$invoice['project_code_snapshot'].' - '.$invoice['project_name_snapshot']:$invoice['current_project_code'].' - '.$invoice['current_project_name'];$purchaseOrderCode=$approved?$invoice['purchase_order_code_snapshot']:$invoice['current_purchase_order_code'];
?>
<div class="page-header mb-4"><div class="row"><div class="col"><div class="page-pretitle"><?=e($invoice['invoice_code'])?></div><h2 class="page-title">فاتورة مورد</h2></div><div class="col-auto"><?php if($approved):?><a class="btn" target="_blank" href="/supplier-invoices/<?=(int)$invoice['id']?>/print">طباعة</a><?php endif;?><?php if($invoice['status']==='draft'&&$canEdit):?><a class="btn" href="/supplier-invoices/<?=(int)$invoice['id']?>/edit">تعديل</a><?php endif;?></div></div></div>
<div class="card mb-4"><div class="card-body"><div class="row g-3"><?php foreach(['الحالة'=>$status,'رقم الفاتورة'=>$invoice['invoice_number'],'التاريخ'=>$invoice['invoice_date'],'الاستحقاق'=>$invoice['due_date']?:'—','المورد'=>$vendor,'المشروع'=>$project,'المرجع'=>$invoice['reference']?:'—'] as $label=>$value):?><div class="col-md-3"><div class="small text-secondary"><?=$label?></div><strong><?=e((string)$value)?></strong></div><?php endforeach;?><?php if($invoice['purchase_order_id']!==null):?><div class="col-md-3"><div class="small text-secondary">أمر الشراء</div><strong><a href="/purchase-orders/<?=(int)$invoice['purchase_order_id']?>"><?=e((string)$purchaseOrderCode)?></a></strong></div><?php endif;?></div></div></div>
<div class="card mb-4"><div class="table-responsive"><table class="table card-table"><thead><tr><th>#</th><th>الوصف</th><th>القسم / كود التكلفة</th><th>المبلغ</th></tr></thead><tbody><?php foreach($lines as $line):?><tr><td><?=(int)$line['sort_order']?></td><td><?=e($line['description'])?></td><td><?=e(($approved?$line['work_section_code_snapshot']:$line['current_section_code']).' / '.($approved?$line['cost_code_snapshot']:$line['current_cost_code']))?></td><td><?=decimal_format($line['amount'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="3">الإجمالي</th><th><?=decimal_format($invoice['total_amount']??$displayTotal)?></th></tr></tfoot></table></div></div>
<?php if($invoice['status']==='draft'):?><div class="d-flex gap-2"><?php if($canApprove):?><form method="post" action="/supplier-invoices/<?=(int)$invoice['id']?>/approve" class="js-confirm-form" data-confirm="سيتم اعتماد الفاتورة وإنشاء تكاليف المشروع ولن يمكن التعديل بعدها."><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">اعتماد</button></form><?php endif;?><?php if($canCancel):?><form method="post" action="/supplier-invoices/<?=(int)$invoice['id']?>/cancel" class="js-confirm-form" data-confirm="هل تريد إلغاء المسودة؟"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-danger">إلغاء</button></form><?php endif;?></div><?php endif;?>
